#include <stdio.h>
#include <dlfcn.h>

int main() {
  void *handle = dlopen("./mylib.so", RTLD_LAZY);
  if (!handle) {
    fprintf(stderr, "Error opening shared library: %s\n", dlerror());
    return 1;
  }

  void (*myfunc)(char*) = dlsym(handle, "my_function");
  if (!myfunc) {
    fprintf(stderr, "Error getting symbol: %s\n", dlerror());
    dlclose(handle);
    return 1;
  }

  myfunc("Hello from dynamic library!");
  dlclose(handle);
  return 0;
}
